<?php if ( ! defined( 'ABSPATH' ) ) { exit; } $thread_id = absint( $args['thread_id'] ); $thread = function_exists( 'messages_get_message_thread' ) ? messages_get_message_thread( $thread_id ) : false; ?><article class="sd-conversation" data-sd-thread="<?php echo esc_attr( $thread_id ); ?>"><header><a href="<?php echo esc_url( sd_messages_nav_url() ); ?>" class="sd-back-link">← <?php esc_html_e( 'All messages', 'social-discovery' ); ?></a><h2><?php esc_html_e( 'Conversation', 'social-discovery' ); ?></h2></header><?php if ( ! $thread || ! function_exists( 'sd_core_message_thread_allowed' ) || ! sd_core_message_thread_allowed( $thread_id ) ) : ?><div class="sd-empty-state"><h2><?php esc_html_e( 'Conversation unavailable', 'social-discovery' ); ?></h2><p><?php esc_html_e( 'You do not have access to this conversation.', 'social-discovery' ); ?></p></div><?php else : ?><div class="sd-message-history"><?php foreach ( $thread->messages as $message ) : ?><article class="sd-message <?php echo (int) $message->sender_id === get_current_user_id() ? 'is-mine' : ''; ?>"><div class="sd-message-bubble"><p><?php echo nl2br( esc_html( $message->message ) ); ?></p><time><?php echo esc_html( $message->date_sent ); ?></time></div></article><?php endforeach; ?></div><?php get_template_part( 'template-parts/messaging/compose-message', null, array( 'thread_id' => $thread_id ) ); endif; ?></article>
